-- rule all_children_retired (row): parameterized; p1 boolean, p2 boolean
SELECT t."part_id" FROM "sxc_rules"."part" t WHERE (t."retired" IS NOT NULL AND t."retired" = CAST(:p1 AS boolean)) AND (EXISTS (SELECT 1 FROM "sxc_rules"."bom_line" e WHERE e."parent_id" = t."part_id" AND e."child_id" IS NOT NULL) AND NOT EXISTS (SELECT 1 FROM "sxc_rules"."bom_line" e WHERE e."parent_id" = t."part_id" AND e."child_id" IS NOT NULL AND NOT EXISTS (SELECT 1 FROM "sxc_rules"."part" n WHERE n."part_id" = e."child_id" AND (n."retired" IS NOT NULL AND n."retired" = CAST(:p2 AS boolean)))));

-- rule all_children_retired: view
CREATE OR REPLACE VIEW "sxc_out"."v_rule_all_children_retired" AS
SELECT r.*, row_number() OVER (ORDER BY r."part_id" COLLATE "C" NULLS FIRST) AS ord FROM (SELECT t."part_id" FROM "sxc_rules"."part" t WHERE (t."retired" IS NOT NULL AND t."retired" = CAST(E'false' AS boolean)) AND (EXISTS (SELECT 1 FROM "sxc_rules"."bom_line" e WHERE e."parent_id" = t."part_id" AND e."child_id" IS NOT NULL) AND NOT EXISTS (SELECT 1 FROM "sxc_rules"."bom_line" e WHERE e."parent_id" = t."part_id" AND e."child_id" IS NOT NULL AND NOT EXISTS (SELECT 1 FROM "sxc_rules"."part" n WHERE n."part_id" = e."child_id" AND (n."retired" IS NOT NULL AND n."retired" = CAST(E'true' AS boolean)))))) r;

-- example all_children_retired[0]: parameterized; 26 parameters
WITH "sxc_ex_part"("retired", "part_id") AS (VALUES (CAST(:p1 AS boolean), CAST(:p2 AS text)), (CAST(:p3 AS boolean), CAST(:p4 AS text)), (CAST(:p5 AS boolean), CAST(:p6 AS text)), (CAST(:p7 AS boolean), CAST(:p8 AS text)), (CAST(:p9 AS boolean), CAST(:p10 AS text)), (CAST(:p11 AS boolean), CAST(:p12 AS text))), "sxc_ex_bom_line"("parent_id", "child_id") AS (VALUES (CAST(:p13 AS text), CAST(:p14 AS text)), (CAST(:p15 AS text), CAST(:p16 AS text)), (CAST(:p17 AS text), CAST(:p18 AS text)), (CAST(:p19 AS text), CAST(:p20 AS text)), (CAST(:p21 AS text), CAST(:p22 AS text)), (CAST(:p23 AS text), CAST(:p24 AS text))) SELECT * FROM (SELECT t."part_id" FROM "sxc_ex_part" t WHERE (t."retired" IS NOT NULL AND t."retired" = CAST(:p25 AS boolean)) AND (EXISTS (SELECT 1 FROM "sxc_ex_bom_line" e WHERE e."parent_id" = t."part_id" AND e."child_id" IS NOT NULL) AND NOT EXISTS (SELECT 1 FROM "sxc_ex_bom_line" e WHERE e."parent_id" = t."part_id" AND e."child_id" IS NOT NULL AND NOT EXISTS (SELECT 1 FROM "sxc_ex_part" n WHERE n."part_id" = e."child_id" AND (n."retired" IS NOT NULL AND n."retired" = CAST(:p26 AS boolean)))))) r;
